def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if float(opp.get('budget', 0)) > budget:
                rich_opp += 1
            if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 10)) <= 3:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2
    if supply_tight:
        danger += 1

    if danger >= 5:
        bid = max(72.0, highest_prev + 4.0)
    elif danger >= 3:
        bid = max(58.0, avg_prev * 0.72 + 3.0)
    else:
        if supply_loose and hp >= 5 and no_water == 0:
            bid = 16.0 + 2.0 * urgent_opp
        elif highest_prev >= 120:
            bid = 28.0 if hp >= 5 and no_water == 0 else 74.0
        elif highest_prev >= 95:
            bid = 34.0 if hp >= 6 and no_water == 0 and supply_loose else 63.0
        elif highest_prev >= 70:
            bid = min(highest_prev + 2.0, 78.0)
        elif highest_prev > 0:
            bid = max(36.0, highest_prev + 1.5)
        else:
            bid = 40.0

    if rich_opp >= 2 and danger <= 2:
        bid *= 0.9
    if day >= 8 and (hp <= 4 or no_water >= 1):
        bid = max(bid, 68.0)

    reserve = 0.0
    if hp >= 5 and no_water == 0 and day <= 7:
        reserve = 35.0
    elif hp >= 3 and day <= 8:
        reserve = 18.0

    max_affordable = max(0.0, budget - reserve)
    if max_affordable <= 0:
        return min(budget, 12.0)

    bid = min(bid, max_affordable)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, just bid enough to get water safely.
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.45))

    # Read yesterday bids from immediate previous_trace only.
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Estimate competitive price band from yesterday.
    if yesterday_bids:
        sorted_bids = sorted(yesterday_bids)
        # Use median-ish to avoid chasing the top.
        mid_idx = int(len(sorted_bids) // 2)
        median_bid = float(sorted_bids[mid_idx])
        max_prev = float(max(sorted_bids))
    else:
        median_bid = DAILY_SALARY * 1.1
        max_prev = DAILY_SALARY * 1.4

    # Supply pressure: if supply is near minimum, competition likely increases.
    # Normalize to [0,1] where 0=MIN_SUPPLY, 1=MAX_SUPPLY.
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        supply_tightness = 0.5
    else:
        supply_tightness = 1.0 - ((supply - MIN_SUPPLY) / denom)
        if supply_tightness < 0.0:
            supply_tightness = 0.0
        if supply_tightness > 1.0:
            supply_tightness = 1.0

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Base bid around yesterday median; adjust for my urgency and supply tightness.
    urgency = 0.0
    if hp <= 2:
        urgency += 0.35
    elif hp <= 4:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 0.25
    elif no_water_days == 1:
        urgency += 0.12

    # If supply is tight, raise bid; if ample, keep it closer to median.
    tight_factor = 0.75 + 0.5 * supply_tightness  # in [0.75,1.25]

    target = median_bid * tight_factor

    # If my hp is very low, consider bidding closer to the previous max (but cap by budget).
    if hp <= 1:
        target = 0.6 * target + 0.4 * max_prev
    elif hp <= 2:
        target = (1.0 - urgency) * target + urgency * max_prev
    else:
        # Mild urgency nudges upward.
        target = target * (1.0 + 0.25 * urgency)

    # Also ensure we bid at least a fraction of a daily salary to stay in the historical band.
    min_floor = DAILY_SALARY * (0.55 + 0.25 * supply_tightness)
    target = max(target, min_floor)

    # Final cap by budget; also avoid extreme bids that likely mirror Alex's overcommit.
    # Keep below ~0.95*max_prev unless budget forces it.
    cap = 0.95 * max_prev
    if cap < 1.0:
        cap = DAILY_SALARY * 1.2

    bid = min(target, cap)
    bid = min(bid, budget)

    # If budget is too low, bid whatever remains (but must be non-negative).
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    base_bid = 0

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.98
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.85
    else:
        if highest_prev_bid > 0:
            if highest_prev_bid >= DAILY_SALARY * 0.7:
                base_bid = highest_prev_bid * 1.05
            else:
                base_bid = max(DAILY_SALARY * 0.6, highest_prev_bid + 5)
        else:
            base_bid = DAILY_SALARY * 0.6

    num_slots = int(current_supply // WATER_REQ)
    if num_slots == 0:
        num_slots = 1 

    num_competitors = len(alive_opponents) + 1

    if num_competitors > num_slots:
        competition_factor = num_competitors / num_slots
        base_bid *= min(1.25, competition_factor)
    else:
        base_bid *= 0.95

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2 and my_status['hp'] < EPISODE_DAYS:
        base_bid *= 1.15

    final_bid = max(1.0, min(my_status['budget'], base_bid))

    if my_status['hp'] <= 1:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.99)

    return final_bid

